test("durable atomic writes tolerate same-process concurrency without temporary-file collisions", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-durable-write-")); t.after(() => fs.rm(root, { recursive: true, force: true })); const filename = path.join(root, "nested", "state.json"), values = Array.from({ length: 32 }, (_, index) => `${JSON.stringify({ index })}\n`);
  await Promise.all(values.map((value) => durableAtomicWrite(filename, value)));
  assert.equal(await fs.readFile(filename, "utf8"), values.at(-1)); assert.deepEqual((await fs.readdir(path.dirname(filename))).filter((name) => name.endsWith(".tmp")), []);
  await assert.rejects(durableAtomicWrite(filename, null), /invalid durable atomic write/);
});

test("durable appends preserve same-process submission order", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-durable-append-")); t.after(() => fs.rm(root, { recursive: true, force: true })); const filename = path.join(root, "nested", "audit.jsonl"), lines = Array.from({ length: 32 }, (_, index) => `${index}\n`);
  await Promise.all(lines.map((line) => durableAppendFile(filename, line)));
  assert.equal(await fs.readFile(filename, "utf8"), lines.join("")); await assert.rejects(durableAppendFile(filename, null), /invalid durable append/);
});

test("content-bound durable rewrites serialize behind appends and reject changed sources", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-durable-rewrite-")); t.after(() => fs.rm(root, { recursive: true, force: true })); const filename = path.join(root, "audit.jsonl"), original = "original\n", digest = crypto.createHash("sha256").update(original).digest("hex"); await fs.writeFile(filename, original); await Promise.all([durableAppendFile(filename, "appended\n"), assert.rejects(durableAtomicRewriteIfUnchanged(filename, digest, "replacement\n"), /source changed/)]); assert.equal(await fs.readFile(filename, "utf8"), "original\nappended\n");
});

test("graceful shutdown drains HTTP before flushing durable audit work", async () => {
  const calls = [], server = { closeWebSocketClients() { calls.push("close-websockets"); }, close(callback) { calls.push("close"); queueMicrotask(() => { calls.push("drained"); callback(); }); }, closeIdleConnections() { calls.push("close-idle"); }, auditSink: { async flush() { calls.push("audit-flushed"); } } };
  await shutdownIndexer({ server, oracleWatcher: { stop() { calls.push("oracle-stopped"); } }, stopWatching() { calls.push("watch-stopped"); } });
  assert.deepEqual(calls, ["oracle-stopped", "watch-stopped", "close-websockets", "close", "close-idle", "drained", "audit-flushed"]);
  await assert.rejects(shutdownIndexer({ server: { close(callback) { callback(new Error("close failed")); } } }), /close failed/);
});

test("graceful shutdown force-closes stalled HTTP only after its deadline", async () => {
  const calls = [], server = { closeWebSocketClients() { calls.push("close-websockets"); }, close(callback) { calls.push("close"); this.callback = callback; }, closeIdleConnections() { calls.push("close-idle"); }, closeAllConnections() { calls.push("force-close"); this.callback(); }, auditSink: { async flush() { calls.push("audit-flushed"); } } }, result = await shutdownIndexer({ server, timeoutMs: 5 }); assert.deepEqual(result, { forced: true }); assert.deepEqual(calls, ["close-websockets", "close", "close-idle", "force-close", "audit-flushed"]);
  await assert.rejects(shutdownIndexer({ server: { close() {} }, timeoutMs: 5 }), /cannot force-close/);
});

test("graceful shutdown cannot be held open by an active WebSocket", async () => {
  const store = new IndexStore("unused"); await store.load(); const server = createServer({ webSocketHeartbeatMs: 60_000 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); const socket = new WebSocket(`ws://127.0.0.1:${server.address().port}/ws`); await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject; }); const closed = new Promise((resolve) => { socket.onclose = resolve; });
  let timeout; try { await Promise.race([shutdownIndexer({ server }), new Promise((_, reject) => { timeout = setTimeout(() => reject(new Error("shutdown timed out with active WebSocket")), 1_000); })]); } finally { clearTimeout(timeout); } const event = await closed; assert.equal(event.code, 1001); assert.equal(server.webSocketStats.activeClients, 0);
});
