test("Orca Whirlpool math matches official exact tick and swap vectors", () => {
  assert.deepEqual([orcaSqrtPriceX64AtTick(-443_636), orcaSqrtPriceX64AtTick(-1), orcaSqrtPriceX64AtTick(0), orcaSqrtPriceX64AtTick(1), orcaSqrtPriceX64AtTick(443_636)].map(String), ["4295048016", "18445821805675392311", "18446744073709551616", "18447666387855959850", "79226673515401279992447579055"]);
  const step = computeStaticFeeExactInputStep({ sqrtPriceX64: 9n << 64n, targetSqrtPriceX64: 4n << 64n, liquidity: 1296n, amountRemaining: 1000n, feeRateMillionths: 20_000n, zeroForOne: true });
  assert.deepEqual(step, { nextSqrtPriceX64: (4n << 64n).toString(), amountIn: "180", amountOut: "6480", feeAmount: "4", reachedTarget: true });
  const quote = quoteOrcaStaticFeeExactInput({ sqrtPriceX64: orcaSqrtPriceX64AtTick(0), currentTick: 0, liquidity: "1000000", amountIn: "10000", feeRateMillionths: 3000, aToB: false, limitTick: 200, tickSpacing: 10, initializedTicks: [{ tick: 100, liquidityNetRaw: "250000", liquidityGrossRaw: "250000" }] });
  assert.deepEqual({ crossedTicks: quote.crossedTicks, endLiquidityRaw: quote.endLiquidityRaw, fullyConsumed: quote.fullyConsumed }, { crossedTicks: 1, endLiquidityRaw: "1250000", fullyConsumed: true });
});

