test("API authentication and quotas fail closed", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-api-audit-")), auditLogFile = path.join(root, "audit.jsonl"), store = new IndexStore("unused"); await store.load(); const config = { staleAfterMs: 120_000, apiKeys: ["secret"], rateLimitPerMinute: 2, auditLogFile };
  const server = createServer(config, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise((resolve) => server.close(resolve))); const endpoint = `http://127.0.0.1:${server.address().port}/api/stats`;
  assert.equal((await fetch(endpoint)).status, 401); assert.equal((await fetch(endpoint, { headers: { "x-api-key": "wrong" } })).status, 401);
  assert.equal((await fetch(`http://127.0.0.1:${server.address().port}/internal/feed/health`)).status, 401);
  const first = await fetch(endpoint, { headers: { authorization: "Bearer secret" } }); assert.equal(first.status, 200); assert.equal(first.headers.get("x-ratelimit-remaining"), "1");
  assert.equal((await fetch(endpoint, { headers: { "x-api-key": "secret" } })).status, 200);
  const limited = await fetch(endpoint, { headers: { "x-api-key": "secret" } }); assert.equal(limited.status, 429); assert.ok(limited.headers.get("retry-after"));
  await server.auditSink.flush(); const audit = (await fs.readFile(auditLogFile, "utf8")).trim().split("\n").map(JSON.parse); assert.equal(audit.length, 6); assert.ok(audit.every((row) => row.schemaVersion === 1 && row.path && Number.isFinite(row.durationMs) && row.quotaUnits === 1)); assert.equal(audit.some((row) => JSON.stringify(row).includes("secret")), false); assert.equal(audit.at(-1).statusCode, 429); assert.match(audit.at(-1).identityHash, /^[0-9a-f]{64}$/);
});

test("distributed Redis quotas are atomic, identity-safe, weighted, and fail closed", async (t) => {
  const compiled = compileRedisQuotaRequest("tenant-secret-name", 123, 60_000, null, 2), wire = compiled.payload.toString(); assert.match(wire, /EVAL/); assert.match(wire, /INCRBY/); assert.match(wire, /terminal_dex:quota:123:[0-9a-f]{64}/); assert.equal(wire.includes("tenant-secret-name"), false); assert.throws(() => compileRedisQuotaRequest("tenant", 1, 60_000, null, 101), /invalid Redis quota request/);
  let written; const admit = createRedisQuotaAdmitter({}, () => { const listeners = {}; const socket = { once(name, handler) { listeners[name] = handler; return socket; }, on(name, handler) { listeners[name] = handler; return socket; }, write(payload) { written = payload; queueMicrotask(() => listeners.data(Buffer.from("*2\r\n:2\r\n:45000\r\n"))); }, destroy() {} }; queueMicrotask(() => listeners.connect()); return socket; }); const admission = await admit("tenant-a", 3, 7_380_000, 2); assert.deepEqual(admission, { count: 2, remaining: 1, retryAfterSeconds: 45, window: 123 }); assert.match(written.toString(), /INCRBY/); assert.equal(written.includes(Buffer.from("tenant-a")), false); assert.throws(() => createRedisQuotaAdmitter({ host: "redis.example.com" }), /loopback-only/);
  const store = new IndexStore("unused"); await store.load(); let count = 0; const server = createServer({ staleAfterMs: 120_000, apiKeys: ["secret"], rateLimitPerMinute: 2, distributedQuotaEnabled: true, quotaAdmitter: async () => ({ count: ++count, remaining: Math.max(0, 2 - count), retryAfterSeconds: 17 }) }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const endpoint = `http://127.0.0.1:${server.address().port}/api/stats`, headers = { "x-api-key": "secret" }; assert.equal((await fetch(endpoint, { headers })).status, 200); assert.equal((await fetch(endpoint, { headers })).status, 200); const limited = await fetch(endpoint, { headers }); assert.equal(limited.status, 429); assert.equal(limited.headers.get("retry-after"), "17");
  const unavailable = createServer({ staleAfterMs: 120_000, apiKeys: ["secret"], rateLimitPerMinute: 2, distributedQuotaEnabled: true }, store); await new Promise((resolve) => unavailable.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => unavailable.close(resolve))); const failed = await fetch(`http://127.0.0.1:${unavailable.address().port}/api/stats`, { headers }); assert.equal(failed.status, 503); assert.equal((await failed.json()).error, "distributed_quota_unavailable");
  const weighted = createServer({ staleAfterMs: 120_000, apiKeys: ["secret"], rateLimitPerMinute: 2 }, store); await new Promise((resolve) => weighted.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => weighted.close(resolve))); const weightedBase = `http://127.0.0.1:${weighted.address().port}`, rpcHeaders = { ...headers, "content-type": "application/json" }, rpcBatch = [{ jsonrpc: "2.0", id: 1, method: "getIndexerStats" }, { jsonrpc: "2.0", id: 2, method: "getIndexerStats" }]; assert.equal((await fetch(`${weightedBase}/rpc`, { method: "POST", headers: rpcHeaders, body: JSON.stringify(rpcBatch) })).status, 200); assert.equal((await fetch(`${weightedBase}/api/stats`, { headers })).status, 429);
});

