  store.state.holderSnapshots[mint] = { slot: 10, observedAt: new Date(now).toISOString() }; job = compileWarehouseProjections(store).jobs.find((row) => row.type === "account_snapshot"); assert.deepEqual({ reason: job.payload.reason, sourceSlot: job.payload.sourceSlot }, { reason: "incomplete_account_evidence", sourceSlot: 10 });
  const complete = { genesisHash: MAINNET_GENESIS_HASH, slot: 10, observedAt: new Date(now - 121_000).toISOString(), sourceHash: "a".repeat(64), accountCount: 1, complete: true, mintInfo: { supply: "100", decimals: 6, mintAuthority: null, freezeAuthority: null }, accounts: [{ tokenAccount: "account", owner: "wallet", programId: SPL_TOKEN_PROGRAM, amountRaw: "100", decimals: 6 }] }; store.state.holderSnapshots[mint] = complete; job = compileWarehouseProjections(store).jobs.find((row) => row.type === "account_snapshot"); assert.equal(job.payload.reason, "stale");
  complete.observedAt = new Date(now).toISOString(); complete.genesisHash = "legacy-devnet"; job = compileWarehouseProjections(store).jobs.find((row) => row.type === "account_snapshot"); assert.equal(job.payload.reason, "incomplete_account_evidence");
