test("WebSocket inbound parser handles TCP fragmentation and rejects invalid client frames", () => {
  const clientFrame = (opcode, payload = Buffer.alloc(0), { masked = true, fin = true } = {}) => { const body = Buffer.from(payload), header = Buffer.alloc(masked ? 6 : 2), mask = Buffer.from([1, 2, 3, 4]); header[0] = (fin ? 0x80 : 0) | opcode; header[1] = (masked ? 0x80 : 0) | body.length; if (masked) mask.copy(header, 2); const encoded = Buffer.from(body); if (masked) for (let index = 0; index < encoded.length; index++) encoded[index] ^= mask[index % 4]; return Buffer.concat([header, encoded]); };
  const socket = () => ({ writes: [], endings: [], write(value) { this.writes.push(Buffer.from(value)); }, end(value) { this.endings.push(Buffer.from(value)); } });
  let peer = socket(), parse = createInboundFrameParser(peer), ping = clientFrame(0x9, "ok"); parse(ping.subarray(0, 3)); assert.equal(peer.writes.length, 0); parse(ping.subarray(3)); assert.equal(peer.writes.length, 1); assert.equal(peer.writes[0][0] & 0x0f, 0x0a); assert.equal(peer.writes[0].subarray(2).toString(), "ok");
  peer = socket(); parse = createInboundFrameParser(peer, 4); parse(Buffer.concat(Array.from({ length: 20 }, () => clientFrame(0x9, "ping")))); assert.equal(peer.writes.length, 20);
  peer = socket(); let protocolCloses = 0; createInboundFrameParser(peer, 4_096, () => protocolCloses++)(clientFrame(0x9, "bad", { masked: false })); assert.equal(peer.endings[0].readUInt16BE(2), 1002); assert.equal(protocolCloses, 1);
  peer = socket(); createInboundFrameParser(peer)(clientFrame(0x1, "unsupported")); assert.equal(peer.endings[0].readUInt16BE(2), 1003);
  peer = socket(); createInboundFrameParser(peer)(clientFrame(0x9, "fragment", { fin: false })); assert.equal(peer.endings[0].readUInt16BE(2), 1002);
  peer = socket(); createInboundFrameParser(peer, 4)(clientFrame(0x9, "12345")); assert.equal(peer.endings[0].readUInt16BE(2), 1009);
  const closePayload = (code, reason = Buffer.alloc(0)) => { const value = Buffer.alloc(2 + reason.length); value.writeUInt16BE(code); Buffer.from(reason).copy(value, 2); return value; };
  peer = socket(); createInboundFrameParser(peer)(clientFrame(0x8, closePayload(1000, Buffer.from("done")))); assert.deepEqual(peer.endings[0].subarray(2), closePayload(1000, Buffer.from("done")));
  peer = socket(); createInboundFrameParser(peer)(clientFrame(0x8, closePayload(1005))); assert.equal(peer.endings[0].readUInt16BE(2), 1002);
  peer = socket(); createInboundFrameParser(peer)(clientFrame(0x8, closePayload(1000, Buffer.from([0xc3, 0x28])))); assert.equal(peer.endings[0].readUInt16BE(2), 1007);
});

test("WebSocket handshake requires canonical RFC 6455 upgrade evidence", () => {
  const request = { method: "GET", headers: { upgrade: "websocket", connection: "keep-alive, Upgrade", "sec-websocket-version": "13", "sec-websocket-key": Buffer.alloc(16, 7).toString("base64") } }; assert.equal(validWebSocketHandshake(request), true);
  for (const invalid of [{ ...request, method: "POST" }, { ...request, headers: { ...request.headers, upgrade: "h2c" } }, { ...request, headers: { ...request.headers, connection: "keep-alive" } }, { ...request, headers: { ...request.headers, "sec-websocket-version": "12" } }, { ...request, headers: { ...request.headers, "sec-websocket-key": "not-a-key" } }, { ...request, headers: { ...request.headers, "sec-websocket-key": Buffer.alloc(15).toString("base64") } }]) assert.equal(validWebSocketHandshake(invalid), false);
});

