test("WebSocket upgrades share tenant quotas and durable commercial metering", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-websocket-audit-")), auditLogFile = path.join(root, "audit.jsonl"), store = new IndexStore("unused"); t.after(() => fs.rm(root, { recursive: true, force: true })); await store.load(); const server = createServer({ apiKeys: ["secret"], rateLimitPerMinute: 1, auditLogFile, webSocketHeartbeatMs: 60_000 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const credential = Buffer.from("secret").toString("base64url"), url = `ws://127.0.0.1:${server.address().port}/ws`;
  assert.equal(webSocketRateLimitHeaders({ limit: 1, remaining: 0, retryAfterSeconds: 60 }), "X-RateLimit-Limit: 1\r\nX-RateLimit-Remaining: 0\r\n"); assert.equal(webSocketRateLimitHeaders({ limit: 1, remaining: 0, retryAfterSeconds: 60 }, true), "X-RateLimit-Limit: 1\r\nX-RateLimit-Remaining: 0\r\nRetry-After: 60\r\n"); assert.equal(webSocketRateLimitHeaders({ limit: 0, remaining: 0, retryAfterSeconds: 60 }), ""); const first = new WebSocket(url, ["indexer.v1", `bearer.${credential}`]); await new Promise((resolve, reject) => { first.onopen = resolve; first.onerror = reject; }); const response = await new Promise((resolve, reject) => { const socket = net.createConnection({ host: "127.0.0.1", port: server.address().port }), chunks = []; socket.once("error", reject); socket.once("connect", () => socket.write(`GET /ws HTTP/1.1\r\nHost: 127.0.0.1\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: ${Buffer.alloc(16, 9).toString("base64")}\r\nX-API-Key: secret\r\n\r\n`)); socket.on("data", (chunk) => chunks.push(chunk)); socket.once("close", () => resolve(Buffer.concat(chunks).toString())); }); assert.match(response, /^HTTP\/1\.1 429 Too Many Requests\r\n/); assert.match(response, /\r\nX-RateLimit-Limit: 1\r\n/); assert.match(response, /\r\nX-RateLimit-Remaining: 0\r\n/); assert.match(response, /\r\nRetry-After: ([1-9]|[1-5][0-9]|60)\r\n/); await server.auditSink.flush(); const rows = (await fs.readFile(auditLogFile, "utf8")).trim().split("\n").map(JSON.parse); assert.deepEqual(rows.map((row) => [row.path, row.statusCode, row.quotaUnits]), [["/ws", 101, 1], ["/ws", 429, 1]]); assert.ok(rows.every((row) => Number.isFinite(row.durationMs) && row.durationMs >= 0)); assert.equal(JSON.stringify(rows).includes("secret"), false); first.close();
});

test("WebSocket admission fails closed at capacity and recovers after disconnect", async (t) => {
  const store = new IndexStore("unused"); await store.load(); const server = createServer({ webSocketHeartbeatMs: 60_000, webSocketMaxClients: 1 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const url = `ws://127.0.0.1:${server.address().port}/ws`;
  const first = new WebSocket(url); await new Promise((resolve, reject) => { first.onopen = resolve; first.onerror = reject; });
  const saturated = new WebSocket(url), rejected = await new Promise((resolve) => { saturated.onerror = resolve; }); assert.ok(rejected); assert.equal(first.readyState, WebSocket.OPEN);
  let metrics = await (await fetch(`http://127.0.0.1:${server.address().port}/metrics`)).text(); assert.match(metrics, /terminal_dex_websocket_clients 1/); assert.match(metrics, /terminal_dex_websocket_capacity_rejections_total 1/);
  await new Promise((resolve) => { first.onclose = resolve; first.close(); });
  const replacement = new WebSocket(url); await new Promise((resolve, reject) => { replacement.onopen = resolve; replacement.onerror = reject; }); assert.equal(replacement.readyState, WebSocket.OPEN); replacement.close(); metrics = await (await fetch(`http://127.0.0.1:${server.address().port}/metrics`)).text(); assert.match(metrics, /terminal_dex_websocket_capacity_rejections_total 1/);
});

